class Solution:
 def isPathCrossing(self,path):
  x=y=0;seen={(0,0)}
  for c in path:
   if c=='N':y+=1
   elif c=='S':y-=1
   elif c=='E':x+=1
   else:x-=1
   if (x,y) in seen:return True
   seen.add((x,y))
  return False

class Solution:
 def canMakeArithmeticProgression(self,arr):
  arr.sort();d=arr[1]-arr[0]
  return all(arr[i]-arr[i-1]==d for i in range(2,len(arr)))

class Solution:
 def numIdenticalPairs(self,nums):
  seen={};ans=0
  for x in nums:ans+=seen.get(x,0);seen[x]=seen.get(x,0)+1
  return ans

class Solution:
 def restoreString(self,s,indices):
  out=['']*len(s)
  for i,c in enumerate(s):out[indices[i]]=c
  return ''.join(out)

class Solution:
 def countGoodTriplets(self,arr,a,b,c):
  ans=0
  for i in range(len(arr)):
   for j in range(i+1,len(arr)):
    if abs(arr[i]-arr[j])>a:continue
    for k in range(j+1,len(arr)):
     if abs(arr[j]-arr[k])<=b and abs(arr[i]-arr[k])<=c:ans+=1
  return ans

class Solution:
 def diagonalSum(self,mat):
  n=len(mat);ans=sum(mat[i][i]+mat[i][n-1-i] for i in range(n))
  if n%2:ans-=mat[n//2][n//2]
  return ans

class Solution:
 def numSpecial(self,mat):
  rows=[sum(r) for r in mat];cols=[sum(mat[i][j] for i in range(len(mat))) for j in range(len(mat[0]))]
  return sum(mat[i][j]==1 and rows[i]==1 and cols[j]==1 for i in range(len(mat)) for j in range(len(mat[0])))

class ParkingSystem:
