 def addCar(self,carType):
  if self.left[carType]==0:return False
  self.left[carType]-=1;return True

class Solution:
 def maxDepth(self,s):
  depth=best=0
  for c in s:
   if c=='(':depth+=1;best=max(best,depth)
   elif c==')':depth-=1
  return best
